export fn long_division(v:[*]const i64,n:usize)i64{if(n!=2)return -1;const a0=v[0];const b0=v[1];if(a0< -1000000 or a0>1000000 or b0< -10000 or b0>10000)return -1;if(b0==0)return 0;const neg=(a0<0)!=(b0<0);var a=if(a0<0)-a0 else a0;const b=if(b0<0)-b0 else b0;var ds:[16]i64=@splat(0);var len:usize=0;if(a==0)len=1;while(a>0){ds[len]=@rem(a,10);a=@divTrunc(a,10);len+=1;}var rem:i64=0;var q:i64=0;while(len>0){len-=1;rem=rem*10+ds[len];var d:i64=0;while(rem>=b){rem-=b;d+=1;}q=q*10+d;}if(neg)return -q;return q;}
